"""Directed and seeded stimulus; expected results are generated by the Rust tool."""

from copy import deepcopy
import random

U32 = (1 << 32) - 1
U64 = (1 << 64) - 1


def word(value):
    return {"kind": "word", "value": value}


def ramp(duration=100, elapsed=0):
    return {"kind": "ramp", "value": {"start": -(1 << 31), "target": (1 << 31) - 1,
                                      "duration": duration, "elapsed": elapsed}}


def ins(kind, **fields):
    return {"kind": "process_" + kind, **fields}


def case(name, instructions, memory, capacity, *, quantum=32, budget=None, writes=None):
    return {"name": name,
            "program": {"chunk_frames": 1, "instructions": instructions, "quantum": quantum,
                        "jobs_per_quantum": len(instructions) if budget is None else budget},
            "initial_state": {"memory": memory}, "queue_capacity": capacity,
            "steps": [{"writes": items} for items in (writes if writes is not None else [[]])]}


def directed(depths):
    program_depth, state_depth, capacity = depths
    for kind, fields in [
        ("input", dict(port=65535, destination=417)),
        ("mix", dict(left=65535, right=32768, destination=91)),
        ("output", dict(source=65534, port=513)),
    ]:
        yield case(kind + "-identifiers", [ins(kind, **fields)], [], capacity)
    yield case("empty", [], [], capacity, writes=[[], [], []])
    yield case("empty-admission-error", [], [], capacity, budget=capacity + 1)
    for quantum in (0, 1, 32, U32):
        for duration, elapsed in ((0, 0), (0, U32), (1, 0), (33, 1), (U32, U32 - 15), (U32, U32)):
            yield case(f"ramp-q{quantum}-d{duration}-e{elapsed}",
                       [ins("gain", ramp=0, source=65535, destination=172)],
                       [ramp(duration, elapsed)], capacity, quantum=quantum, writes=[[], [], []])
    yield case("gain-wrong-type", [ins("gain", ramp=0, source=1, destination=2)], [word(0)], capacity)
    yield case("gain-bad-address", [ins("gain", ramp=65535, source=1, destination=2)], [], capacity)
    yield case("disabled-playback-ignores-unused-addresses", [ins("loop_playback",
               view=65535, position=65535, length=65535, enabled=0, destination=123)], [word(0)], capacity)
    yield case("disabled-capture-ignores-unused-address", [ins("loop_capture",
               view=65535, enabled=0, source=456)], [word(0)], capacity)
    yield case("disabled-capture-with-no-queue-reservation", [ins("loop_capture",
               view=65535, enabled=0, source=456)], [word(0)], capacity, budget=0)
    playback = ins("loop_playback", view=0, enabled=1, position=2, length=3, destination=633)
    capture = ins("loop_capture", view=0, enabled=1, source=911)
    memory = [word(U32), word(1 << 63), word(U64 - 1), word(U64), ramp()]
    yield case("wide-playback-and-settled-writes", [playback], deepcopy(memory), capacity,
               writes=[[], [{"address": 1, "value": word(0)}],
                       [{"address": 2, "value": word(0)}, {"address": 1, "value": word(U64)}]])
    yield case("capture-nonzero-high-enabled-bits", [capture], deepcopy(memory), capacity)
    for capture_first in (False, True):
        yield case(f"capture-and-playback-{capture_first}",
                   [capture, playback] if capture_first else [playback, capture],
                   deepcopy(memory), capacity)
    for field in ("enabled", "position", "length", "view"):
        for address in (4, 5, 65535):
            bad = {**playback, field: address}
            yield case(f"playback-{field}-address-{address}",
                       [ins("gain", ramp=4, source=1, destination=2), bad], deepcopy(memory), capacity)
    for field in ("enabled", "view"):
        for address in (4, 5, 65535):
            yield case(f"capture-{field}-address-{address}",
                       [{**capture, field: address}], deepcopy(memory), capacity)
    for position, length in ((0, 0), (9, 9), (10, 9), (U64, U64)):
        values = deepcopy(memory)
        values[2], values[3] = word(position), word(length)
        yield case(f"invalid-range-{position}-{length}",
                   [ins("gain", ramp=4, source=1, destination=2), playback], values, capacity)
    yield case("aliased-ramp-updates", [ins("gain", ramp=0, source=1, destination=2),
               ins("gain", ramp=0, source=2, destination=3)], [ramp(71, 7)], capacity,
               writes=[[], [], []])
    yield case("admission-does-not-advance-ramp", [ins("gain", ramp=0, source=1, destination=2)],
               [ramp()], capacity, budget=capacity + 1,
               writes=[[{"address": 0, "value": ramp(777, 17)}]])
    yield case("queue-exhaustion-does-not-advance-failing-gain",
               [ins("gain", ramp=0, source=1, destination=2)] * (capacity + 1),
               [ramp(U32)], capacity, budget=0)
    yield case("ordered-control-write-error", [], [word(U64)], capacity,
               writes=[[{"address": 0, "value": word(7)}, {"address": 1, "value": word(8)}], []])
    yield case("last-program-entry", [ins("loop_capture", view=65535, enabled=0, source=0)]
               * program_depth, [word(0)], capacity, budget=0)
    yield case("last-state-entry", [ins("gain", ramp=state_depth - 1, source=65535, destination=0)],
               [word(U64)] * (state_depth - 1) + [ramp()], capacity)
    yield case("full-fifo", [ins("input", port=index, destination=65535 - index)
                             for index in range(capacity)], [], capacity)
    width = min(8, program_depth, capacity)
    yield case("fifo-wrap-repeated-quanta", [ins("input", port=index * 91, destination=65535 - index)
               for index in range(width)], [], capacity,
               writes=[[] for _ in range(2 * capacity // width + 3)])


def random_cases(depths, seed, count):
    program_depth, state_depth, capacity = depths
    rng = random.Random(seed)
    for index in range(count):
        if state_depth < 6:
            memory = [rng.choice([word(0), word(U32), ramp(U32, rng.getrandbits(32))])]
            candidates = [ins("gain", ramp=0, source=91, destination=633),
                          ins("loop_capture", view=0, enabled=0, source=911),
                          ins("loop_playback", view=0, position=0, length=0, enabled=0, destination=633)]
        else:
            length = rng.choice([1, 17, U64])
            memory = [word(rng.getrandbits(32)), word(rng.choice([0, 1, 1 << 63, U64])),
                      word(rng.randrange(length)), word(length),
                      ramp(rng.choice([0, 33, U32]), rng.getrandbits(32)), word(rng.getrandbits(64))]
            candidates = [ins("gain", ramp=4, source=91, destination=633),
                          ins("loop_capture", view=0, enabled=1, source=911),
                          ins("loop_playback", view=0, position=2, length=3, enabled=1, destination=633)]
        candidates += [ins("input", port=rng.getrandbits(16), destination=rng.getrandbits(16)),
                       ins("mix", left=rng.getrandbits(16), right=rng.getrandbits(16), destination=65535),
                       ins("output", source=rng.getrandbits(16), port=65535)]
        instructions = []
        limit = min(program_depth, 12, capacity + (rng.randrange(4) == 0))
        for _ in range(rng.randrange(limit + 1)):
            instruction = deepcopy(rng.choice(candidates))
            addresses = [field for field in ("ramp", "view", "enabled", "position", "length")
                         if field in instruction]
            if addresses and rng.randrange(6) == 0:
                instruction[rng.choice(addresses)] = rng.choice([len(memory), 65535, 0])
            instructions.append(instruction)
        writes = [[]]
        for _ in range(rng.randrange(1, 5)):
            if len(memory) == 1:
                value = rng.choice([word(0), word(U32), ramp(rng.getrandbits(32), rng.getrandbits(32))])
                update = [{"address": 0, "value": value}]
            else:
                address = rng.randrange(len(memory))
                value = [word(rng.getrandbits(32)), word(rng.choice([0, 1, U64])), word(0),
                         word(rng.choice([0, 17, U64])), ramp(rng.getrandbits(32), rng.getrandbits(32)),
                         word(rng.getrandbits(64))][address]
                update = [{"address": address, "value": value}]
            writes.append(update)
        yield case(f"random-{seed}-{index}", instructions, memory, capacity,
                   quantum=rng.choice([0, 1, 32, U32]),
                   budget=rng.choice([len(instructions)] * 5 + [0, capacity + 1]), writes=writes)
